INSERT INTO public.module (id, name, description, course_id, created, updated) VALUES (1, 'Модуль 1. Основи JavaScript', 'У модулі розглядаються базові поняття мови JavaScript. Студенти навчаться створювати прості програми, працювати зі змінними, різними типами даних та виконувати основні операції над ними.', 2, '2026-08-15 14:55:27.000000', null);
INSERT INTO public.module (id, name, description, course_id, created, updated) VALUES (2, 'Модуль 2. Умови та цикли', 'Модуль присвячений керуванню виконанням програми. Студенти навчаться перевіряти умови, виконувати різний код залежно від результату перевірки та повторювати операції за допомогою циклів.', 2, '2026-08-15 14:56:12.000000', null);
INSERT INTO public.module (id, name, description, course_id, created, updated) VALUES (3, e'Модуль 3. Функції, масиви та об\'єкти
INSERT INTO public.module (id, name, description, course_id, created, updated) VALUES (4, 'Модуль 1. Основи Python', 'У цьому модулі студенти ознайомляться із синтаксисом Python, навчаться створювати змінні, працювати з основними типами даних, отримувати інформацію від користувача та виконувати математичні операції.', 1, '2026-08-15 15:06:05.000000', null);
INSERT INTO public.module (id, name, description, course_id, created, updated) VALUES (5, 'Модуль 2. Умови та цикли', 'Модуль знайомить студентів з основними конструкціями керування програмою. Розглядаються умовні оператори та цикли, які дозволяють створювати складнішу логіку.', 1, '2026-08-15 15:06:44.000000', null);
INSERT INTO public.module (id, name, description, course_id, created, updated) VALUES (6, 'Модуль 3. Функції та структури даних', 'Модуль присвячений функціям та основним структурам даних Python. Студенти навчаться створювати власні функції, використовувати списки, словники та кортежі для збереження й обробки інформації.', 1, '2026-08-15 15:07:15.000000', null);
